/**
 * Form submit helper (Phase D) — fetches one-time token before POST.
 * Loaded only when anti-bot is enabled at OBE build time.
 *
 * Also binds any form that already has `_pf_tok` (not only named lead classes),
 * so token arming still works when markup classes drift.
 */
(function () {
  "use strict";

  function issueUrlFromForm(form) {
    var action = form.getAttribute("action") || "";
    if (!action) return "";
    if (action.indexOf("submit.php") !== -1) {
      return action.replace(/submit\.php(\?.*)?$/i, "form-issue.php$1");
    }
    var base = action.replace(/\/[^/]*$/, "/");
    return base + "form-issue.php";
  }

  function bindForm(form) {
    if (form.getAttribute("data-pf-bound") === "1") return;
    form.setAttribute("data-pf-bound", "1");

    form.addEventListener(
      "submit",
      function (e) {
        if (form.getAttribute("data-pf-armed") === "1") {
          form.removeAttribute("data-pf-armed");
          return;
        }

        var tok = form.querySelector('input[name="_pf_tok"]');
        if (!tok) return;

        e.preventDefault();
        e.stopPropagation();

        var url = issueUrlFromForm(form);
        if (!url) {
          alert("Please try again.");
          return;
        }

        var btn = form.querySelector('button[type="submit"], input[type="submit"]');
        if (btn) btn.disabled = true;

        fetch(url, { credentials: "same-origin", headers: { Accept: "application/json" } })
          .then(function (res) {
            if (!res.ok) throw new Error("issue");
            return res.json();
          })
          .then(function (data) {
            if (!data || !data.tok) throw new Error("issue");
            tok.value = String(data.tok);
            form.setAttribute("data-pf-armed", "1");
            if (typeof form.requestSubmit === "function") {
              form.requestSubmit();
            } else {
              form.submit();
            }
          })
          .catch(function () {
            if (btn) btn.disabled = false;
            alert("Please try again.");
          });
      },
      true,
    );
  }

  function boot() {
    document
      .querySelectorAll("form.js-lead-form, form.js-rf-form, form.leadform")
      .forEach(bindForm);
    document.querySelectorAll('form input[name="_pf_tok"]').forEach(function (tok) {
      if (tok.form) bindForm(tok.form);
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();
